        if (duration != null && beginDate != null && vacationKindId != null) {
          var url = `/api/functions/GetVacationEndDate?dateBegin=${beginDate}&duration=${duration}&userId=${initiatorId}&vacationKindId=${vacationKindId}`;
          ESS.network.sendRequest(url)
          .then(function (newEndDateValue) {
            functions.setValue('EndDate', newEndDateValue);
          });

          var avaliableDays = null;
          var availableKindsAndDays = JSON.parse(functions.getValues()['AvailableKindsAndDays']);
          if (availableKindsAndDays) {
            availableKindsAndDays.forEach(function (vacationData) {
              if (vacationData.Id == vacationKindId) {
                avaliableDays = vacationData.Count;
              }
            });
          }
          var today = new Date();
          var yesterday = new Date(today);
          yesterday.setDate(today.getDate() -1);
          var dateFromControl = new Date(beginDate).getTime();
          var dateBeginFromControl = new Date(beginDate).toLocaleString("ru-RU", { dateStyle: "long" });
          functions.removeError(window.errorDate);
          functions.setValue('Field_Дата_начала_отпуска', dateBeginFromControl);
          functions.setValue('Field_Продолжительность_отпуска', duration);
          if (dateFromControl < yesterday.getTime())
            window.errorDate = functions.showError(ESS.L('@HRPROVACATIONS.ERROR_DATE_BEGIN'));
          functions.removeError(window.errorId);
          if (duration <= 0)
            window.errorId = functions.showError(ESS.L('@HRPROVACATIONS.ERROR_DURATION'));
          if (avaliableDays != null && duration > avaliableDays)
            window.errorId = functions.showError(ESS.L('@HRPROVACATIONS.ERROR_AVALIABLE_DAYS'));
        }

var initiatorId = functions.getValues().Employee;
var beginDate = functions.getValues().BeginDate;
var endDate = formItem.value;
var vacationKindId = functions.getValues().VacationKindId;
functions.removeError(window.errorEndDate);
if (beginDate != null && endDate != null && vacationKindId != null) {
  var url = `/api/functions/DurationInCalendarDaysWithoutHoliday?startDate=${beginDate}&endDate=${endDate}&userId=${initiatorId}&vacationKindId=${vacationKindId}`
  ESS.network.sendRequest(url)
  .then(function (newDuration) {
    if (newDuration < 1) {
      window.errorEndDate = functions.showError(ESS.L('@HRPROVACATIONS.ERROR_DATE_END'));
    }
  });
}

var url = `/api/functions/CheckVacationHasHoliday?periodBegin=${beginDate}&periodEnd=${formItem.value}&employeeId=${initiatorId}&vacationKindId=${vacationKindId}`;
ESS.network.sendRequest(url)
.then(function (warning) {
  if(warning.length > 0)
    ESS.toasts.showToast(warning, ESS.enums.ToastType.WARNING, true);
});

facilityFormItem.onClickEventHandler:
        const dialogId = 'reworkVacationPlanningTool';
        const callDialog = () => {
          if (!Object.keys(context.canShowDialog).length) {
            const timeline = {
              type: ESS.enums.DialogItemType.TEXT,
              name: 'timeline',
              properties: {
                text: `
                  <component
                    name="VacationPlanningTool"
                    public-name="Directum_VacationPlanningTool_1_0"
                    module-name="loaders"
                    loader-name="lk-loader"
                    dialog-id="${dialogId}"
                  />
                `,
              },
            };
            
            const id = {
              type: ESS.enums.DialogItemType.INPUT,
              name: 'AssignmentId',
              properties: {
                initialValue: functions.getValues().AssignmentId,
                isHidden: true,
              },
            };

            const performerId = {
              type: ESS.enums.DialogItemType.INPUT,
              name: 'PerformerId',
              properties: {
                initialValue: functions.getValues().Employee,
                isHidden: true,
              },
            };

            const vacationKind = {
              type: ESS.enums.DialogItemType.INPUT,
              name: 'VacationKind',
              properties: {
                initialValue: functions.getValues().VacationKindId,
                isHidden: true,
              },
            };

            const beginDate = {
              type: ESS.enums.DialogItemType.INPUT,
              name: 'BeginDate',
              properties: {
                initialValue: functions.getValues().BeginDate,
                isHidden: true,
              },
            };

            const duration = {
              type: ESS.enums.DialogItemType.INPUT,
              name: 'Duration',
              properties: {
                initialValue: functions.getValues().Duration,
                isHidden: true,
              },
            };

            const endDate = {
              type: ESS.enums.DialogItemType.INPUT,
              name: 'EndDate',
              properties: {
                initialValue: functions.getValues().EndDate,
                isHidden: true,
              },
            };

            const entityGuid = {
              type: ESS.enums.DialogItemType.INPUT,
              name: 'EntityGuid',
              properties: {
                initialValue: '82835b9b-0070-4df6-b5de-2a7a5e99677f',
                isHidden: true,
              },
            };

            const items = [
              timeline,
              id,
              performerId,
              vacationKind,
              beginDate,
              duration,
              endDate,
              entityGuid
            ];

            ESS.dialogs.createDialog({
              id: dialogId,
              properties: {
                width: ESS.enums.DialogWidth.WIDE,
                isFullScreen: true,
              },
              title: ESS.L('@HRPROVACATIONS.FACILITIES_SCHEDULEVACATION_DIALOG_TITLE'),
              items,
            });
            clearInterval(intervalId);
          }
        }

        let intervalId = setInterval(callDialog, 300);

facility.openingEventHandler:
    context.canShowDialog = {};
    context.sendRequest = (...args) => {
      const key = Date.now();
      context.canShowDialog[key] = '';
      return ESS.network.sendRequest(...args).finally(() => delete context.canShowDialog[key]);
    };
    // HACK Получение автора задания, чтобы получить только его отпуска.
    ESS.network.sendRequest(`/api/functions/GetTaskEmployee?assignmentId=${functions.getValues().AssignmentId}`)
      .then(function (employee) {
        var employeeId = employee.id
        functions.setValue('Employee', employeeId);

        return ESS.network.sendRequest(`/api/functions/GetVacationStatementTemplateId?employeeId=${employeeId}&isShiftVacation=false`);
      })
      .then(function (VacationStatementData) {
        var templateId = JSON.parse(VacationStatementData.TemplateId);
        var docKindId = JSON.parse(VacationStatementData.DocumentKindId);
        functions.setValue('TemplateId', templateId);
        functions.setValue('DocumentKindId', docKindId);
        functions.setValue('IsFromEssAccount', true);

        return ESS.network.sendRequest(`/api/functions/GetVacationStatementId?assignmentId=${functions.getValues().AssignmentId}`);
      })
      .then(function (statementId) {
        functions.setValue('StatementId', statementId);
        return ESS.network.sendRequest(`/api/functions/GetCurrentVacation?assignmentId=${functions.getValues().AssignmentId}`)
      })
      .then(function (oldVacation) {
        var begin = oldVacation.Begin;
        var duration = oldVacation.Duration;
        var end  = oldVacation.End;
        functions.setValue('Field_Дата_начала_отпуска', new Date(begin).toLocaleString("ru-RU", { dateStyle: "long" }));
        functions.setValue('Field_Продолжительность_отпуска', duration);
        functions.setValue('Field_Вид_отпуска', oldVacation.VacationKindName.toLowerCase());
        functions.setValue('VacationKindId', oldVacation.VacationId);
        functions.setValue('BeginDate', new Date(begin));
        functions.setValue('Duration', duration);
        functions.setValue('EndDate', new Date(end));
        resolve();
      })
      .catch(function (error) {
        ESS.toasts.showToast(error.message, ESS.enums.ToastType.ERROR, false);
        reject();
      });
